try {
    this.uiState.selectedAttachment = undefined;

    if (!page) {
        this.uiState.currentPage = 1;
    }

    const pageNumber = page ?? this.uiState.currentPage ?? 1;
    entityType = entityType ?? this.uiState.targetEntityType;
    entityId = entityId ?? this.uiState.targetEntityId;

    const capitalizedEntityType = entityType[0].toUpperCase() + entityType.slice(1);
    const entityUrl = `attachment/${capitalizedEntityType}/${entityId}`;

    // 1. Track the ID of the request
    const requestIdentity = { entityId, page: pageNumber };
    this.uiState.lastAttachmentRequest = requestIdentity;

    // 2. Start the loading state by assigning the Promise
    this.uiState.currentAttachments = this.entityCacheService.getAll(
        undefined, entityUrl, pageNumber, limit, undefined, query, clearCache, 'attachment'
    ).then((result) => {

        // 3. RACE CONDITION CHECK
        const isLatest = (
            this.uiState.lastAttachmentRequest.entityId === requestIdentity.entityId &&
            this.uiState.lastAttachmentRequest.page === requestIdentity.page
        );

        if (isLatest) {
            // ONLY assign if no newer request has started.
            this.uiState.attachmentsInternalData = result.entities ?? [];
            this.uiState.currentAttachments = this.uiState.attachmentsInternalData;
        }

        return result.entities ?? [];

    }).catch((e) => {
        console.error("Error fetching attachments:", e);
        if (this.uiState.lastAttachmentRequest.page === pageNumber) {
            this.notificationService.notify({ 
                alertType: "error",
                alertDescription: "Failed to load attachments.",
                dismissIn: 5_000
            });
            this.uiState.currentAttachments = [];
        }
        return []; 
    });

} catch (e) {
    console.error(`Critical error:`, e);
    this.uiState.currentAttachments = [];
}

if (!file) return;

const entityType = this.uiState.targetEntityType;
const capitalizedEntityType = entityType[0].toUpperCase() + entityType.slice(1);
const entityId = this.uiState.targetEntityId;
const entityName = this.uiState.targetEntityName;

const fileName = file.name;
const isFileTypeValid = this.helpers._isFileTypeValid(file, this.ALLOWED_FILE_TYPES);
const isFileSizeValid = this.helpers._isFileSizeValid(file, this.MAX_FILE_SIZE_IN_MB);

// 1. Check File Type
if (!isFileTypeValid) {
    this.notificationService.notify({
        alertType: "error",
        alertDescription: this.enService.components.attachmentComponent.messages.getInvalidTypeError(this.ALLOWED_FILE_TYPES),
        dismissIn: this.notifyConfig.dismissInMs.ERROR
    });
    this.attachmentForm.file = null;
    return;
}

// 2. Check File Size
if (!isFileSizeValid) {
    this.notificationService.notify({
        alertType: "error",
        alertDescription: this.enService.components.attachmentComponent.messages.getFileSizeError(this.MAX_FILE_SIZE_IN_MB),
        dismissIn: this.notifyConfig.dismissInMs.ERROR
    });
    this.attachmentForm.file = null;
    return;
}

return new Promise((resolve) => {
    try {
        // 1. Prepare the Data
        const formData = new FormData();
        formData.append('file', file);

        // 2. Initialize XHR
        const xhr = new XMLHttpRequest();
        const url = `${this.dataService.apiBaseUrl}/attachment/${capitalizedEntityType}/${entityId}`;

        // 3. Track Progress
        this.helpers._resetUploadState();
        this.uiState.uploadMessage = this.enService.components.attachmentComponent.messages.getPreparingUpload(fileName);
        this.uiState.isUploading = true;

        xhr.upload.addEventListener("progress", (event) => {
            if (event.lengthComputable) {
                // Calculate percentage
                const percentComplete = Math.round((event.loaded / event.total) * 100);

                if (percentComplete === 100) {
                    this.uiState.uploadMessage = this.enService.components.attachmentComponent.messages.getFinalizingUpload(fileName);
                }

                // Update the UI state
                // Use $timeout because XHR events run outside Angular's digest cycle
                this.$timeout(() => {
                    this.uiState.uploadProgress = percentComplete;
                });
            }
        });

        // 4. Handle Completion
        xhr.addEventListener("load", () => {
            this.$timeout(() => {
                this.helpers._resetUploadState();

                if (xhr.status >= 200 && xhr.status < 300) {

                    // Only reload table if same entity
                    if (entityType === this.uiState.targetEntityType && entityId === this.uiState.targetEntityId) {
                        this.uiState.currentPage = 1;
                        this.loaders.loadAllAttachmentsByEntity();
                    }

                    const successMessage = this.enService.components.attachmentComponent.messages.getUploadSuccess(fileName, entityName);
                    this.uiState.uploadMessage = successMessage;
                    this.notificationService.notify({
                        alertType: "success",
                        alertDescription: successMessage,
                        dismissIn: this.notifyConfig.dismissInMs.SUCCESS
                    });
                    const response = JSON.parse(xhr.responseText);
                    resolve(response);
                } else {
                    this.helpers._onUploadFailure(fileName, entityName, this.notifyConfig.dismissInMs.ERROR);
                    resolve({ success: false, status: xhr.status, error: `Upload failed with status ${xhr.status}` });
                }
            });
        });

        // 5. Handle Errors
        xhr.addEventListener("error", () => {
            this.$timeout(() => {
                this.helpers._resetUploadState();
                this.helpers._onUploadFailure(fileName, entityName, this.notifyConfig.dismissInMs.ERROR);
                resolve({ success: false, error: "Network error during upload." });
            });
        });

        // 6. Send the Request
        this.uiState.uploadMessage = this.enService.components.attachmentComponent.messages.getUploading(fileName);
        xhr.open("POST", url);

        // Set Headers
        const headers = this.authService.getHeaders();
        Object.keys(headers).forEach(key => {
            // Note: Do NOT manually set 'Content-Type' for FormData; 
            // the browser needs to set the boundary string itself.
            if (key.toLowerCase() !== 'content-type') {
                xhr.setRequestHeader(key, headers[key]);
            }
        });

        xhr.send(formData);

    } catch (e) {
        this.helpers._resetUploadState();
        this.helpers._onUploadFailure(fileName, entityName, this.notifyConfig.dismissInMs.ERROR);
        resolve({ success: false, error: e });
    }
});

if (!attachment || !attachment.url) {
    this.notificationService.notify({
        alertType: "error",
        alertDescription: "Download URL is missing or invalid.",
        dismissIn: 5_000
    });
    return;
}

const { url, fileName } = attachment;

try {
    // Create a hidden anchor element
    const link = document.createElement('a');
    link.href = url;

    // The 'download' attribute suggests a filename to the browser.
    link.setAttribute('download', fileName);

    // Ensure it opens/downloads in a way that doesn't replace the current app state
    link.target = '_blank';

    // Append to body, click, and remove
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

} catch (e) {
    console.error("Manual download failed, falling back to window.open", e);
    window.open(url, '_blank');
}

if (!attachment || !attachment.attachmentId) {
    this.notificationService.notify({
        alertType: "error",
        alertDescription: "Attachment ID is missing or invalid.",
        dismissIn: 5_000
    });
    return;
}

const { attachmentId, fileName } = attachment;
const entityType = this.uiState.targetEntityType;
const entityName = this.uiState.targetEntityName;

try {
    this.uiState.isDeleting = true;
    const options = {
        displayName: fileName,
        modalData: this.utilityService.formatEntityForDisplay(attachment)
    };

    const result = await this.dataService.deleteData(
        "attachment",
        attachmentId,
        options,
        {
            entityType: entityType[0].toUpperCase() + entityType.slice(1)
        }
    );

    if (result?.result !== 'cancel') {
        const successMessage = this.enService.components.attachmentComponent.messages.getDeleteSuccess(fileName, entityName);
        this.notificationService.notify({
            alertType: "success",
            alertDescription: successMessage,
            dismissIn: this.notifyConfig.dismissInMs.SUCCESS
        });
        this.loaders.loadAllAttachmentsByEntity();
    }

} catch (e) {
    console.error("Failed to delete attachment: ", e);
    this.notificationService.notify({
        alertType: "error",
        alertDescription: this.enService.components.attachmentComponent.messages.getDeleteFailed(fileName, entityName),
        dismissIn: this.notifyConfig.dismissInMs.ERROR
    });
} finally {
    this.uiState.isDeleting = false;
}

limitInMB = limitInMB ?? this.MAX_FILE_SIZE_IN_MB;

if (!file || !file.size) return false;

// 1MB = 1024 * 1024 bytes
const limitInBytes = limitInMB * 1024 * 1024;

return file.size <= limitInBytes;

allowedTypes = allowedTypes ?? this.ALLOWED_FILE_TYPES;

if (!file || !file.name || !allowedTypes.length) return false;

const fileName = file.name.toLowerCase();
// Check if the filename ends with any of the allowed extensions
return allowedTypes.some(ext => fileName.endsWith(ext.toLowerCase()));

const failedMessage = this.enService.components.attachmentComponent.messages.getUploadFailed(fileName, entityName);
this.uiState.uploadMessage = failedMessage;
this.notificationService.notify({
    alertType: "error",
    alertDescription: failedMessage,
    dismissIn
});

this.uiState.isUploading = false;
this.uiState.uploadProgress = 0;
this.uiState.uploadMessage = "";
this.attachmentForm.file = null;

