return [
    {
        label: "Attachment Id",
        value: "attachmentId"
    },
    {
        label: "File Name",
        value: "fileName"
    },
    {
        label: "File Type",
        value: "mimeType"
    },
    {
        label: "Size",
        value: "size"
    },
    {
        label: "Uploaded",
        value: "uploadedOn"
    }
];

const displayColumnNames = [
    "File Name",
    "Size",
    "Uploaded"
];

const displayColumnOptions = {
    valueKey: {
        "Uploaded": "uploadedOn"
    },
    cellTemplateJsExpression: {
        "Uploaded": "$ctrl.utilityService.formatDisplayDate(value)",
        "Size": "$ctrl.utilityService.formatBytes(value)"
    }
};

return {
    columnNames: displayColumnNames,
    options: displayColumnOptions
}
